from qiskit import qasm3
from qiskit.primitives import StatevectorSampler

program = """
OPENQASM 3.0;
include "stdgates.inc";

qubit[4] q;
bit[4] c;

h q[0];
cx q[0], q[1];
cx q[1], q[2];
cx q[2], q[3];
c = measure q;
"""

qc = qasm3.loads(program)
counts = StatevectorSampler(seed=8674).run([qc], shots=2000).result()[0].data.c.get_counts()
