import qsharp

qsharp.init()
qsharp.eval("""
operation Ghz(n : Int) : Result[] {
    use qs = Qubit[n];
    H(qs[0]);
    for i in 1..n - 1 {
        CNOT(qs[i - 1], qs[i]);
    }
    return MResetEachZ(qs);
}
""")

shots = 1000
results = qsharp.run("Ghz(4)", shots=shots)
counts = {}
for shot in results:
    key = "".join("1" if str(x) == "One" else "0" for x in shot)
    counts[key] = counts.get(key, 0) + 1
print("GHZ distribution:", counts)
assert set(counts) <= {"0" * 4, "1" * 4}

