import math
import qsharp

qsharp.init()
qsharp.eval("""
operation Teleport(theta : Double) : Result {
    use (msg, alice, bob) = (Qubit(), Qubit(), Qubit());
    Ry(theta, msg);            // state to teleport
    H(alice);                  // entangle alice-bob
    CNOT(alice, bob);
    CNOT(msg, alice);          // Bell measurement
    H(msg);
    if MResetZ(alice) == One { X(bob); }
    if MResetZ(msg) == One   { Z(bob); }
    return MResetZ(bob);
}
""")

theta, shots = 1.421, 1000
results = qsharp.run(f"Teleport({theta})", shots=shots)
p1 = sum(1 for x in results if str(x) == "One") / shots
expected = math.sin(theta / 2) ** 2
print(f"P(One) on receiver = {p1:.4f}, theory = {expected:.4f}")
assert abs(p1 - expected) < 0.05

from qiskit import qasm3, transpile
from qiskit_aer import AerSimulator

program = """
OPENQASM 3.0;
include "stdgates.inc";

qubit q;
bit flip;
bit final;

h q;                  // random coin
flip = measure q;
if (flip == true) {   // active reset
    x q;
}
final = measure q;
"""

qc = qasm3.loads(program)
backend = AerSimulator()
counts = backend.run(transpile(qc, backend), shots=4096).result().get_counts()
print("Counts (bits ordered 'final flip'):", counts)
final_ones = sum(v for k, v in counts.items() if k.replace(" ", "")[0] == "1")
print(f"P(final=1) = {final_ones / 4096} (should be 0: reset always succeeds)")
assert final_ones == 0

import pennylane as qml
from pennylane import numpy as np

layers, k = 3, 1
dev = qml.device("default.qubit", wires=1)

@qml.qnode(dev)
def model(x, w):
    for l in range(layers):
        qml.RZ(x, wires=0)        # re-upload the data in every layer
        qml.RY(w[l], wires=0)
    return qml.expval(qml.PauliZ(0))

np.random.seed(2332)
X = np.linspace(0, 2 * np.pi, 30)
Y = np.cos(k * X)

def loss(w):
    return np.mean((np.array([model(x, w) for x in X]) - Y) ** 2)

w = np.random.uniform(-np.pi, np.pi, layers, requires_grad=True)
opt = qml.AdamOptimizer(0.2)
for i in range(80):
    w = opt.step(loss, w)
    if (i + 1) % 20 == 0:
        print(f"epoch {i+1}: mse = {loss(w):.5f}")
print(f"Final MSE = {loss(w):.5f}")

