import qsharp

qsharp.init()
qsharp.eval("""
import Std.Math.*;
import Std.Convert.*;
import Std.Arrays.*;

operation ReflectAboutMarked(qs : Qubit[], marked : Bool[]) : Unit {
    within {
        for i in 0..Length(qs) - 1 {
            if not marked[i] { X(qs[i]); }
        }
    } apply {
        Controlled Z(Most(qs), Tail(qs));
    }
}

operation ReflectAboutUniform(qs : Qubit[]) : Unit {
    within {
        ApplyToEachA(H, qs);
        ApplyToEachA(X, qs);
    } apply {
        Controlled Z(Most(qs), Tail(qs));
    }
}

operation GroverSearch(n : Int, marked : Bool[]) : Result[] {
    use qs = Qubit[n];
    ApplyToEach(H, qs);
    let iterations = Round(PI() / 4.0 * Sqrt(IntAsDouble(2 ^ n)));
    for _ in 1..iterations {
        ReflectAboutMarked(qs, marked);
        ReflectAboutUniform(qs);
    }
    return MResetEachZ(qs);
}
""")

target = "000"
marked = "[" + ", ".join("true" if b == "1" else "false" for b in target) + "]"
shots = 200
results = qsharp.run(f"GroverSearch({len(target)}, {marked})", shots=shots)
hits = sum(1 for shot in results
           if "".join("1" if str(x) == "One" else "0" for x in shot) == target)
print(f"Found |{target}> in {hits}/{shots} shots ({hits / shots:.2%})")
assert hits / shots > 0.8

