import pennylane as qml
from pennylane import numpy as np

edges = [(0, 1), (0, 2), (1, 2), (1, 3), (1, 4), (2, 3), (2, 4)]
n = max(max(e) for e in edges) + 1
p = 2
dev = qml.device("default.qubit", wires=n)

def layer(gamma, beta):
    for i, j in edges:
        qml.IsingZZ(2 * gamma, wires=[i, j])
    for w in range(n):
        qml.RX(2 * beta, wires=w)

H = qml.Hamiltonian([0.5] * len(edges),
                    [qml.PauliZ(i) @ qml.PauliZ(j) for i, j in edges])

@qml.qnode(dev)
def cost(params):
    for w in range(n):
        qml.Hadamard(wires=w)
    for k in range(p):
        layer(params[0, k], params[1, k])
    return qml.expval(H)            # minimizing sum ZZ/2 maximizes the cut

@qml.qnode(dev)
def probs(params):
    for w in range(n):
        qml.Hadamard(wires=w)
    for k in range(p):
        layer(params[0, k], params[1, k])
    return qml.probs(wires=range(n))

np.random.seed(7244)
params = np.random.uniform(0, np.pi, (2, p), requires_grad=True)
opt = qml.AdamOptimizer(0.1)
for i in range(120):
    params = opt.step(cost, params)

pr = probs(params)
best = int(np.argmax(pr))
bits = format(best, f"0{n}b")
cut = sum(1 for i, j in edges if bits[i] != bits[j])
opt_cut = max(sum(1 for i, j in edges if format(x, f"0{n}b")[i] != format(x, f"0{n}b")[j])
              for x in range(2 ** n))
print(f"Most probable bitstring: {bits} (p={pr[best]:.3f}), cut = {cut}, optimal = {opt_cut}")

