from fractions import Fraction
from math import gcd
import numpy as np
from qiskit import QuantumCircuit
from qiskit.circuit.library import UnitaryGate
from qiskit.primitives import StatevectorSampler

N, a = 15, 7
n_count = 8          # counting qubits
n_work = 4           # work register holds values mod 15

def c_amod15(a, power):
    """Controlled multiplication by a^power mod 15 as a permutation unitary."""
    U = np.zeros((16, 16))
    for x in range(16):
        U[(x * pow(a, power, N)) % N if x < N else x, x] = 1
    return UnitaryGate(U, label=f"{a}^{power} mod 15").control(1)

qc = QuantumCircuit(n_count + n_work, n_count)
qc.h(range(n_count))
qc.x(n_count)                     # work register starts in |1>
for j in range(n_count):
    qc.append(c_amod15(a, 2 ** j), [j] + list(range(n_count, n_count + n_work)))

def iqft(qc, qubits):
    for q in range(len(qubits) // 2):
        qc.swap(qubits[q], qubits[-q - 1])
    for j in range(len(qubits)):
        for k in range(j):
            qc.cp(-np.pi / 2 ** (j - k), qubits[k], qubits[j])
        qc.h(qubits[j])

iqft(qc, list(range(n_count)))
qc.measure(range(n_count), range(n_count))

counts = StatevectorSampler(seed=4121).run([qc], shots=512).result()[0].data.c.get_counts()
factors = set()
for bits in sorted(counts, key=counts.get, reverse=True):
    phase = int(bits, 2) / 2 ** n_count
    r = Fraction(phase).limit_denominator(N).denominator
    if r % 2 == 0 and pow(a, r, N) == 1:
        for f in (gcd(pow(a, r // 2) - 1, N), gcd(pow(a, r // 2) + 1, N)):
            if f not in (1, N):
                factors.add(f)
print(f"a = {a}, recovered factors of 15: {sorted(factors)}")
assert factors == {3, 5}

