import Std.Math.*;
import Std.Convert.*;
import Std.Arrays.*;

operation ReflectAboutMarked(qs : Qubit[], marked : Bool[]) : Unit {
    within {
        for i in 0..Length(qs) - 1 {
            if not marked[i] { X(qs[i]); }
        }
    } apply {
        Controlled Z(Most(qs), Tail(qs));
    }
}

operation ReflectAboutUniform(qs : Qubit[]) : Unit {
    within {
        ApplyToEachA(H, qs);
        ApplyToEachA(X, qs);
    } apply {
        Controlled Z(Most(qs), Tail(qs));
    }
}

operation GroverSearch(n : Int, marked : Bool[]) : Result[] {
    use qs = Qubit[n];
    ApplyToEach(H, qs);
    let iterations = Round(PI() / 4.0 * Sqrt(IntAsDouble(2 ^ n)));
    for _ in 1..iterations {
        ReflectAboutMarked(qs, marked);
        ReflectAboutUniform(qs);
    }
    return MResetEachZ(qs);
}
""")

